const uint offset = id * 2;
const uint frequency = (id / (32 * 64)) * 64 + id % 64;
const float a = x[offset];
const float b = x[offset + 1];
const float co = c[frequency];
const float si = s[frequency];
const float r1 = fma(a, co, -(b * si));
const float r2 = fma(-b, si, a * co);
const float i1 = fma(b, co, a * si);
const float i2 = fma(a, si, b * co);
first_first[offset] = r1; first_first[offset + 1] = i1;
first_second[offset] = r1; first_second[offset + 1] = i2;
second_first[offset] = r2; second_first[offset + 1] = i1;
second_second[offset] = r2; second_second[offset + 1] = i2;
natural[offset] = a * co - b * si;
natural[offset + 1] = a * si + b * co;
